<div class="space-y-6"><div><h1 class="text-3xl font-bold">Bibliotecas y carga masiva</h1><p class="text-slate-400">Registra discos o montajes autorizados y agrega películas o temporadas completas en una sola tarea.</p></div>
<section class="bg-slate-900 border border-slate-800 rounded-xl p-5"><h2 class="text-xl font-bold mb-3">Escanear discos de balanceadores</h2><div class="flex flex-wrap gap-3"><?php foreach($libraries as $l):?><?php if($l['server_id']!==null):?><form method="post" action="/libraries/remote"><?=$csrf->field()?><input type="hidden" name="library_id" value="<?=$l['id']?>"><input type="hidden" name="operation" value="scan"><button class="bg-cyan-700 px-4 py-2 rounded">Escanear e importar <?=htmlspecialchars($l['name'])?></button></form><?php endif?><?php endforeach?></div></section>
<section class="bg-slate-900 border border-slate-800 rounded-xl p-5"><h2 class="text-xl font-bold mb-4">Añadir biblioteca</h2><form method="post" action="/libraries" class="grid md:grid-cols-4 gap-3"><?=$csrf->field()?><input required name="name" placeholder="Nombre" class="bg-slate-800 p-2 rounded"><select name="type" class="bg-slate-800 p-2 rounded"><option value="mounted">Disco montado</option><option value="local">Disco local</option><option value="nfs">NFS</option><option value="smb">SMB</option></select><select name="content_type" class="bg-slate-800 p-2 rounded"><option value="series">Series</option><option value="movie">Películas</option><option value="mixed">Mixto</option></select><input required name="mount_path" placeholder="/mnt/media/series" class="bg-slate-800 p-2 rounded"><select name="server_id" class="bg-slate-800 p-2 rounded"><option value="">Visible desde el servidor principal</option><?php foreach($servers as $s):?><option value="<?=$s['id']?>"><?=htmlspecialchars($s['name'])?> (solo balanceador)</option><?php endforeach?></select><input type="number" min="1" name="min_free_gb" value="10" class="bg-slate-800 p-2 rounded"><input type="number" min="1" name="priority" value="100" class="bg-slate-800 p-2 rounded"><label class="flex items-center gap-2"><input type="checkbox" name="active" value="1"> Activar</label><button class="md:col-span-4 bg-cyan-700 p-2 rounded">Guardar biblioteca</button></form></section>
<section class="grid gap-4"><?php foreach($libraries as $l):?><article class="bg-slate-900 border border-slate-800 rounded-xl p-5"><div class="flex flex-wrap gap-3"><div class="mr-auto"><h2 class="text-xl font-bold"><?=htmlspecialchars($l['name'])?></h2><p class="text-slate-400"><?=htmlspecialchars($l['mount_path'])?> · <?=htmlspecialchars($l['server_name']??'Principal/compartido')?> · <?=number_format((int)$l['files_count'])?> archivos</p></div><span class="<?=$l['active']?'text-emerald-400':'text-amber-400'?>"><?=$l['active']?'Activa':'Inactiva'?></span></div><?php if($l['server_id']===null):?><div class="flex gap-3 mt-4"><form method="post" action="/libraries/scan"><?=$csrf->field()?><input type="hidden" name="library_id" value="<?=$l['id']?>"><input type="hidden" name="type" value="series"><button class="bg-indigo-700 px-4 py-2 rounded">Importar todos los episodios</button></form><form method="post" action="/libraries/scan"><?=$csrf->field()?><input type="hidden" name="library_id" value="<?=$l['id']?>"><input type="hidden" name="type" value="movie"><button class="bg-slate-700 px-4 py-2 rounded">Importar todas las películas</button></form></div><?php else:?><div class="mt-4 flex flex-wrap gap-3"><form method="post" action="/libraries/remote"><?=$csrf->field()?><input type="hidden" name="library_id" value="<?=$l['id']?>"><input type="hidden" name="operation" value="inventory"><button class="bg-indigo-700 px-4 py-2 rounded">Buscar y resolver symlinks</button></form><form method="post" action="/libraries/remote"><?=$csrf->field()?><input type="hidden" name="library_id" value="<?=$l['id']?>"><input type="hidden" name="operation" value="validate"><button class="bg-emerald-700 px-4 py-2 rounded">Validar todo con FFprobe</button></form><form method="post" action="/libraries/remote" class="flex gap-2" onsubmit="return confirm('Solo se reemplazarán enlaces simbólicos dentro de bibliotecas autorizadas. ¿Continuar?')"><?=$csrf->field()?><input type="hidden" name="library_id" value="<?=$l['id']?>"><input type="hidden" name="operation" value="apply_links"><select required name="target_server_id" class="bg-slate-800 p-2 rounded"><option value="">Balanceador OrionX destino</option><?php foreach($servers as $s):?><option value="<?=$s['id']?>"><?=htmlspecialchars($s['name'])?></option><?php endforeach?></select><button class="bg-amber-700 px-4 py-2 rounded">Recrear enlaces válidos</button></form></div><?php endif?></article><?php endforeach?></section>
<section><h2 class="text-xl font-bold mb-3">Tareas</h2><div class="space-y-2"><?php foreach($jobs as $j):?><div class="bg-slate-900 border border-slate-800 rounded p-3 flex justify-between"><span><?=htmlspecialchars($j['library_name'])?> · <?=htmlspecialchars($j['type'])?></span><span><?=htmlspecialchars($j['status'])?> · <?=$j['files_added']?>/<?=$j['files_seen']?> · conflictos <?=$j['conflicts']?></span></div><?php endforeach?></div></section>
<?php if($conflicts):?><section><h2 class="text-xl font-bold mb-3">Revisión necesaria</h2><div class="space-y-2"><?php foreach($conflicts as $c):?><div class="bg-amber-950/30 border border-amber-800 rounded p-3"><strong><?=htmlspecialchars($c['reason'])?></strong><div class="text-sm break-all"><?=htmlspecialchars($c['relative_path'])?></div></div><?php endforeach?></div></section><?php endif?>
<section><h2 class="text-xl font-bold mb-3">Operaciones remotas</h2><div class="space-y-2"><?php foreach($remoteRuns as $r):?><div class="bg-slate-900 border border-slate-800 rounded p-3"><div class="flex justify-between"><strong><?=htmlspecialchars($r['operation'])?> · <?=htmlspecialchars($r['library_name'])?> → <?=htmlspecialchars($r['server_name'])?></strong><span><?=htmlspecialchars($r['status'])?></span></div><?php if($r['summary']):?><div class="text-sm text-emerald-300"><?=htmlspecialchars($r['summary'])?></div><?php endif?><?php if($r['error_message']):?><div class="text-sm text-red-400"><?=htmlspecialchars(substr($r['error_message'],0,500))?></div><?php endif?></div><?php endforeach?></div></section>
<?php if($links):?><section><h2 class="text-xl font-bold mb-3">Enlaces simbólicos detectados</h2><div class="overflow-x-auto border border-slate-800 rounded"><table class="w-full text-sm"><thead class="bg-slate-900"><tr><th class="p-3 text-left">Enlace</th><th class="text-left">Destino real</th><th>Validación</th><th>Aplicado</th></tr></thead><tbody><?php foreach($links as $x):?><tr class="border-t border-slate-800"><td class="p-3 break-all"><?=htmlspecialchars($x['link_path'])?></td><td class="p-3 break-all"><?=htmlspecialchars($x['target_path']??'—')?></td><td class="text-center <?=$x['valid']?'text-emerald-400':'text-red-400'?>"><?=$x['valid']?'Válido':htmlspecialchars($x['error_message']??'Inválido')?></td><td class="text-center"><?=$x['applied_at']?'Sí':'No'?></td></tr><?php endforeach?></tbody></table></div></section><?php endif?></div>
